"use client";

import { type PointerEvent, useCallback, useEffect, useRef, useState } from "react";
import { type XYPadAxis, type XYPadDirection, type XYPadRatio, type XYPadValue, changedAxes, ratioToValue, sameValue } from "./xy-pad-math";
import { type XYPadDetail, useIsomorphicLayoutEffect } from "./xy-pad-state";

type Options = {
  value: XYPadValue;
  xAxis: XYPadAxis;
  yAxis: XYPadAxis;
  yDirection: XYPadDirection;
  enabled: boolean;
  trackRef: { current: HTMLDivElement | null };
  thumbRef: { current: HTMLDivElement | null };
  setLive: (value: XYPadValue | null) => void;
  onValueChange?: (value: XYPadValue, detail: XYPadDetail) => void;
  onValueCommit: (value: XYPadValue, detail: XYPadDetail) => void;
};

type Drag = {
  id: number;
  start: XYPadValue;
  last: XYPadValue;
  origin: XYPadRatio;
  client: { x: number; y: number };
  shift: boolean;
  element: HTMLElement;
};

const unit = (value: number) => Math.min(Math.max(value, 0), 1);

/** Press to move the point, drag to keep moving it, Shift to stay on one axis and Escape to cancel. */
export function useXYPadDrag(options: Options) {
  const [dragging, setDragging] = useState(false);
  const [pointerFocus, setPointerFocus] = useState(false);
  const drag = useRef<Drag | null>(null);
  const latest = useRef(options);
  useIsomorphicLayoutEffect(() => {
    latest.current = options;
  });

  const ratioAt = useCallback((client: Drag["client"]): XYPadRatio => {
    const box = latest.current.trackRef.current?.getBoundingClientRect();
    if (!box || box.width === 0 || box.height === 0) return { x: 0, y: 0 };
    return { x: unit((client.x - box.left) / box.width), y: unit((client.y - box.top) / box.height) };
  }, []);

  const update = useCallback(
    (active: Drag) => {
      const { xAxis, yAxis, yDirection, setLive, onValueChange, trackRef } = latest.current;
      const ratio = ratioAt(active.client);
      if (active.shift) {
        const box = trackRef.current?.getBoundingClientRect();
        const across = Math.abs(ratio.x - active.origin.x) * (box?.width ?? 1);
        const along = Math.abs(ratio.y - active.origin.y) * (box?.height ?? 1);
        if (across >= along) ratio.y = active.origin.y;
        else ratio.x = active.origin.x;
      }
      const next = ratioToValue(ratio, xAxis, yAxis, yDirection);
      if (sameValue(next, active.last)) return;
      active.last = next;
      setLive(next);
      onValueChange?.(next, { axes: changedAxes(active.start, next), source: "pointer" });
    },
    [ratioAt],
  );

  const finish = useCallback((cancel: boolean) => {
    const active = drag.current;
    if (!active) return;
    drag.current = null;
    const { setLive, onValueChange, onValueCommit } = latest.current;
    const axes = changedAxes(active.start, active.last);
    if (axes.length > 0 && cancel) onValueChange?.(active.start, { axes, source: "pointer" });
    if (axes.length > 0 && !cancel) onValueCommit(active.last, { axes, source: "pointer" });
    setLive(null);
    setDragging(false);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (!dragging) return;
    const onKey = (event: KeyboardEvent) => {
      const active = drag.current;
      if (!active) return;
      if (event.key === "Escape" && event.type === "keydown") {
        event.preventDefault();
        event.stopPropagation();
        finish(true);
      } else if (event.key === "Shift") {
        active.shift = event.shiftKey;
        update(active);
      }
    };
    const onBlur = () => finish(true);
    const onPointerEnd = (event: globalThis.PointerEvent) => {
      if (drag.current?.id === event.pointerId) finish(event.type === "pointercancel");
    };
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("keyup", onKey, true);
    window.addEventListener("blur", onBlur);
    window.addEventListener("pointerup", onPointerEnd);
    window.addEventListener("pointercancel", onPointerEnd);
    return () => {
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("keyup", onKey, true);
      window.removeEventListener("blur", onBlur);
      window.removeEventListener("pointerup", onPointerEnd);
      window.removeEventListener("pointercancel", onPointerEnd);
    };
  }, [dragging, finish, update]);

  useEffect(() => () => finish(true), [finish]);

  const surfaceHandlers = {
    onPointerDown: (event: PointerEvent<HTMLDivElement>) => {
      if (event.defaultPrevented || event.button !== 0 || !options.enabled || drag.current) return;
      event.preventDefault();
      const client = { x: event.clientX, y: event.clientY };
      const active: Drag = { id: event.pointerId, start: options.value, last: options.value, origin: ratioAt(client), client, shift: event.shiftKey, element: event.currentTarget };
      drag.current = active;
      try {
        event.currentTarget.setPointerCapture?.(event.pointerId);
      } catch {
        // The pointer may already have ended; the window listener still finishes the drag.
      }
      setPointerFocus(true);
      options.thumbRef.current?.focus({ preventScroll: true });
      setDragging(true);
      update(active);
    },
    onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
      const active = drag.current;
      if (!active || active.id !== event.pointerId) return;
      active.client = { x: event.clientX, y: event.clientY };
      active.shift = event.shiftKey;
      update(active);
    },
    onPointerUp: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(false);
    },
    onPointerCancel: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(true);
    },
    onLostPointerCapture: (event: PointerEvent<HTMLDivElement>) => {
      if (drag.current?.id === event.pointerId) finish(true);
    },
  };

  return { dragging, pointerFocus, setPointerFocus, surfaceHandlers, isDragging: () => drag.current !== null };
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { NumberField, NumberFieldError, NumberFieldGroup, NumberFieldInput, NumberFieldScrubArea, NumberFieldUnit } from "@/components/ui/number-field";
import { type XYPadAxisName, axisLargeStep, axisPrecision, axisStep } from "./xy-pad-math";
import { useXYPad } from "./xy-pad-state";
import { cn } from "@/lib/utils";

type FieldProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  axis: XYPadAxisName;
};

/** A Number Field for one axis: type, step or drag its label. */
export const XYPadField = forwardRef<HTMLDivElement, FieldProps>(function XYPadField({ axis, className, ...props }, ref) {
  const pad = useXYPad();
  const spec = axis === "x" ? pad.xAxis : pad.yAxis;
  return (
    <NumberField
      ref={ref}
      data-slot="xy-pad-field"
      data-axis={axis}
      className={cn("min-w-0", className)}
      label={spec.label}
      value={pad.value[axis]}
      placeholder={pad.messages.mixed}
      min={spec.min}
      max={spec.max}
      step={axisStep(spec)}
      largeStep={axisLargeStep(spec)}
      precision={axisPrecision(spec)}
      unit={spec.unit}
      disabled={pad.disabled}
      readOnly={pad.readOnly}
      onValueChange={(next) => pad.previewAxis(axis, next)}
      onValueCommit={(next) => pad.commitAxis(axis, next)}
      {...props}
    >
      <NumberFieldGroup>
        <NumberFieldScrubArea className="pl-2 text-xs text-muted-foreground">{spec.shortLabel ?? axis.toUpperCase()}</NumberFieldScrubArea>
        <NumberFieldInput className="min-w-0" />
        <NumberFieldUnit />
      </NumberFieldGroup>
      <NumberFieldError />
    </NumberField>
  );
});

/** A field for each axis, side by side. */
export const XYPadFields = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function XYPadFields({ className, children, ...props }, ref) {
  return (
    <div ref={ref} data-slot="xy-pad-fields" className={cn("grid grid-cols-2 gap-2", className)} {...props}>
      {children ?? (
        <>
          <XYPadField axis="x" />
          <XYPadField axis="y" />
        </>
      )}
    </div>
  );
});

export type XYPadAxisName = "x" | "y";

/** Null means the axis has no single value, such as a mixed selection. */
export type XYPadValue = { x: number | null; y: number | null };
export type XYPadRatio = { x: number; y: number };
export type XYPadDirection = "down" | "up";

export type XYPadAxis = {
  /** Names the axis, such as "Offset X". */
  label: string;
  /** A shorter name for its field, such as "X". */
  shortLabel?: string;
  min: number;
  max: number;
  step?: number;
  /** Used with Shift. Defaults to ten steps. */
  largeStep?: number;
  /** Decimal places kept. Defaults to the decimals of `step`. */
  precision?: number;
  /** Shown after the value, such as "px" or "%". */
  unit?: string;
};

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const decimals = (value: number) => (String(value).split(".")[1] ?? "").length;

export const axisStep = (axis: XYPadAxis) => (axis.step && axis.step > 0 ? axis.step : 1);
export const axisLargeStep = (axis: XYPadAxis) => axis.largeStep ?? axisStep(axis) * 10;
export const axisPrecision = (axis: XYPadAxis) => axis.precision ?? decimals(axisStep(axis));
export const axisMiddle = (axis: XYPadAxis) => snapToAxis((axis.min + axis.max) / 2, axis);

/** Keeps a value inside the axis and on its steps, counted from the minimum. */
export function snapToAxis(value: number, axis: XYPadAxis) {
  const step = axisStep(axis);
  const snapped = axis.min + Math.round((clamp(value, axis.min, axis.max) - axis.min) / step) * step;
  return Number(clamp(snapped, axis.min, axis.max).toFixed(axisPrecision(axis)));
}

/** How far along the axis a value sits, from 0 to 1. */
export function axisRatio(value: number, axis: XYPadAxis) {
  return axis.max === axis.min ? 0 : clamp((value - axis.min) / (axis.max - axis.min), 0, 1);
}

/** Where a value sits on the surface, from the top-left corner. An axis without a value sits in the middle. */
export function valueToRatio(value: XYPadValue, xAxis: XYPadAxis, yAxis: XYPadAxis, direction: XYPadDirection): XYPadRatio {
  const y = value.y === null ? 0.5 : axisRatio(value.y, yAxis);
  return { x: value.x === null ? 0.5 : axisRatio(value.x, xAxis), y: direction === "up" ? 1 - y : y };
}

/** The value at a place on the surface, measured from the top-left corner. */
export function ratioToValue(ratio: XYPadRatio, xAxis: XYPadAxis, yAxis: XYPadAxis, direction: XYPadDirection) {
  const y = direction === "up" ? 1 - ratio.y : ratio.y;
  return {
    x: snapToAxis(xAxis.min + ratio.x * (xAxis.max - xAxis.min), xAxis),
    y: snapToAxis(yAxis.min + y * (yAxis.max - yAxis.min), yAxis),
  };
}

export const sameValue = (a: XYPadValue, b: XYPadValue) => a.x === b.x && a.y === b.y;

export function changedAxes(from: XYPadValue, to: XYPadValue) {
  return (["x", "y"] as const).filter((axis) => from[axis] !== to[axis]);
}

/** Zero when it falls inside the axis, otherwise the middle of the axis. */
export const axisOrigin = (axis: XYPadAxis) => (axis.min < 0 && axis.max > 0 ? 0 : (axis.min + axis.max) / 2);

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useImperativeHandle } from "react";
import { type XYPadAxis, axisOrigin, axisRatio, valueToRatio } from "./xy-pad-math";
import { useXYPad } from "./xy-pad-state";
import { cn } from "@/lib/utils";

/** The area you press and drag. It highlights while dragging and on keyboard focus. Its children sit on the point's travel area. */
export const XYPadSurface = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function XYPadSurface(
  { className, children, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onLostPointerCapture, ...props },
  ref,
) {
  const { disabled, readOnly, dragging, trackRef, surfaceHandlers } = useXYPad();
  return (
    <div
      ref={ref}
      data-slot="xy-pad-surface"
      data-dragging={dragging ? "" : undefined}
      className={cn(
        "relative aspect-square w-full touch-none overflow-hidden rounded-md border border-input bg-muted/40 select-none",
        "data-dragging:border-primary data-dragging:bg-primary/5 has-[:focus-visible:not([data-pointer-focus])]:border-primary",
        disabled ? "cursor-not-allowed opacity-50" : !readOnly && "cursor-crosshair hover:border-muted-foreground/50",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        surfaceHandlers.onPointerDown(event);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        surfaceHandlers.onPointerMove(event);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        surfaceHandlers.onPointerUp(event);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        surfaceHandlers.onPointerCancel(event);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        surfaceHandlers.onLostPointerCapture(event);
      }}
      {...props}
    >
      {/* Inset, so the point stays fully inside the surface at its limits. */}
      <div ref={trackRef} data-slot="xy-pad-track" className="absolute inset-2.5">
        {children ?? (
          <>
            <XYPadGrid />
            <XYPadOrigin />
            <XYPadThumb />
          </>
        )}
      </div>
    </div>
  );
});

type GridProps = ComponentPropsWithoutRef<"div"> & {
  /** How many equal cells run across each direction. */
  cells?: number;
};

/** Equal square cells across the whole surface. Lines sit only between cells, so none run along the edges. */
export const XYPadGrid = forwardRef<HTMLDivElement, GridProps>(function XYPadGrid({ cells = 6, className, ...props }, ref) {
  const stops = Array.from({ length: Math.max(cells - 1, 0) }, (_, index) => ((index + 1) / cells) * 100);
  return (
    <div ref={ref} aria-hidden data-slot="xy-pad-grid" className={cn("pointer-events-none absolute -inset-2.5 text-foreground/15", className)} {...props}>
      {stops.map((stop) => (
        <span key={`x${stop}`} data-slot="xy-pad-grid-line" className="absolute inset-y-0 w-px -translate-x-1/2 bg-current" style={{ left: `${stop}%` }} />
      ))}
      {stops.map((stop) => (
        <span key={`y${stop}`} data-slot="xy-pad-grid-line" className="absolute inset-x-0 h-px -translate-y-1/2 bg-current" style={{ top: `${stop}%` }} />
      ))}
    </div>
  );
});

/** The pad's visible name. Place it above the surface. Pass children to replace the text. */
export const XYPadLabel = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function XYPadLabel({ className, children, ...props }, ref) {
  const { label } = useXYPad();
  return (
    <span ref={ref} aria-hidden data-slot="xy-pad-label" className={cn("truncate text-sm leading-5 text-muted-foreground", className)} {...props}>
      {children ?? label}
    </span>
  );
});

const originRatio = (axis: XYPadAxis) => axisRatio(axisOrigin(axis), axis);

/** A small dot at zero, or at the middle of a range where zero is not inside it. */
export const XYPadOrigin = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function XYPadOrigin({ className, style, ...props }, ref) {
  const { xAxis, yAxis, yDirection } = useXYPad();
  const y = originRatio(yAxis);
  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="xy-pad-origin"
      className={cn("pointer-events-none absolute size-1 -translate-x-1/2 -translate-y-1/2 rounded-full bg-muted-foreground", className)}
      style={{ ...style, left: `${originRatio(xAxis) * 100}%`, top: `${(yDirection === "up" ? 1 - y : y) * 100}%` }}
      {...props}
    />
  );
});

const describe = (axis: XYPadAxis, value: number | null, mixed: string) => `${axis.label} ${value === null ? mixed : `${value}${axis.unit ? ` ${axis.unit}` : ""}`}`;

/** The solid point. It holds keyboard focus for the pad, and grows with a soft halo while dragging. */
export const XYPadThumb = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function XYPadThumb({ className, style, onKeyDown, onBlur, ...props }, ref) {
  const { value, xAxis, yAxis, yDirection, label, disabled, readOnly, dragging, pointerFocus, motion, messages, thumbRef, onThumbKeyDown, onThumbBlur } = useXYPad();
  useImperativeHandle(ref, () => thumbRef.current as HTMLDivElement);
  const ratio = valueToRatio(value, xAxis, yAxis, yDirection);
  const mixed = value.x === null || value.y === null;
  return (
    <div
      ref={thumbRef}
      role="slider"
      tabIndex={disabled ? undefined : 0}
      aria-label={label}
      aria-valuemin={xAxis.min}
      aria-valuemax={xAxis.max}
      aria-valuenow={value.x ?? undefined}
      aria-valuetext={messages.value(describe(xAxis, value.x, messages.mixed), describe(yAxis, value.y, messages.mixed))}
      aria-disabled={disabled || undefined}
      aria-readonly={readOnly || undefined}
      data-slot="xy-pad-thumb"
      data-dragging={dragging ? "" : undefined}
      data-mixed={mixed ? "" : undefined}
      data-pointer-focus={pointerFocus ? "" : undefined}
      className={cn(
        "pointer-events-none absolute size-3 -translate-x-1/2 -translate-y-1/2 rounded-full bg-primary shadow-sm outline-none data-mixed:bg-muted-foreground",
        "data-dragging:scale-125 data-dragging:ring-4 data-dragging:ring-primary/25 data-mixed:data-dragging:ring-muted-foreground/25",
        motion && "transition-[scale,box-shadow] duration-100 ease-out motion-reduce:transition-none",
        className,
      )}
      style={{ ...style, left: `${ratio.x * 100}%`, top: `${ratio.y * 100}%` }}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (!event.defaultPrevented) onThumbKeyDown(event);
      }}
      onBlur={(event) => {
        onBlur?.(event);
        onThumbBlur();
      }}
      {...props}
    />
  );
});

"use client";

import { type KeyboardEvent, forwardRef, useRef, useState } from "react";
import { XYPadFields } from "./xy-pad-fields";
import { type XYPadAxis, type XYPadAxisName, type XYPadValue, axisLargeStep, axisMiddle, axisStep, changedAxes, sameValue, snapToAxis } from "./xy-pad-math";
import { XYPadLabel, XYPadSurface } from "./xy-pad-parts";
import { useXYPadDrag } from "./xy-pad-drag";
import { type XYPadProps, XYPadContext, defaultMessages } from "./xy-pad-state";
import { cn } from "@/lib/utils";

/** Sets two numbers with one point. Without children it shows the label, the surface and a field for each axis. */
export const XYPad = forwardRef<HTMLDivElement, XYPadProps>(function XYPad(
  { value, onValueChange, onValueCommit, xAxis, yAxis, yDirection = "down", label, disabled = false, readOnly = false, motion = true, messages: messageOverrides, className, children, ...props },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const [live, setLive] = useState<XYPadValue | null>(null);
  const trackRef = useRef<HTMLDivElement>(null);
  const thumbRef = useRef<HTMLDivElement>(null);
  const current = live ?? value;
  const editable = !disabled && !readOnly;
  const { dragging, pointerFocus, setPointerFocus, surfaceHandlers, isDragging } = useXYPadDrag({ value, xAxis, yAxis, yDirection, enabled: editable, trackRef, thumbRef, setLive, onValueChange, onValueCommit });

  const onThumbKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!editable || isDragging()) return;
    const move = (axis: XYPadAxisName, spec: XYPadAxis, direction: number) => {
      const amount = (event.shiftKey ? axisLargeStep(spec) : axisStep(spec)) * direction;
      return { ...value, [axis]: snapToAxis((value[axis] ?? axisMiddle(spec)) + amount, spec) };
    };
    const up = yDirection === "up" ? 1 : -1;
    const moves: Record<string, () => XYPadValue> = {
      ArrowLeft: () => move("x", xAxis, -1),
      ArrowRight: () => move("x", xAxis, 1),
      ArrowUp: () => move("y", yAxis, up),
      ArrowDown: () => move("y", yAxis, -up),
      Home: () => ({ ...value, x: xAxis.min }),
      End: () => ({ ...value, x: xAxis.max }),
    };
    const next = moves[event.key]?.();
    if (!next) return;
    event.preventDefault();
    event.stopPropagation();
    setPointerFocus(false);
    if (sameValue(next, value)) return;
    const detail = { axes: changedAxes(value, next), source: "keyboard" as const };
    onValueChange?.(next, detail);
    onValueCommit(next, detail);
  };

  const previewAxis = (axis: XYPadAxisName, number: number) => {
    const next = { ...value, [axis]: number };
    // A cancelled field drag reports the committed number again, which ends the preview.
    setLive(sameValue(next, value) ? null : next);
    onValueChange?.(next, { axes: [axis], source: "field" });
  };

  const commitAxis = (axis: XYPadAxisName, number: number) => {
    setLive(null);
    if (value[axis] !== number) onValueCommit({ ...value, [axis]: number }, { axes: [axis], source: "field" });
  };

  return (
    <XYPadContext.Provider
      value={{
        value: current,
        committed: value,
        xAxis,
        yAxis,
        yDirection,
        label,
        disabled,
        readOnly,
        dragging,
        pointerFocus,
        motion,
        messages,
        trackRef,
        thumbRef,
        surfaceHandlers,
        onThumbKeyDown,
        onThumbBlur: () => setPointerFocus(false),
        previewAxis,
        commitAxis,
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="xy-pad" data-disabled={disabled ? "" : undefined} className={cn("grid w-40 max-w-full gap-2", className)} {...props}>
        {children ?? (
          <>
            <XYPadLabel />
            <XYPadSurface />
            <XYPadFields />
          </>
        )}
      </div>
    </XYPadContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, createContext, useContext, useEffect, useLayoutEffect } from "react";
import type { XYPadAxis, XYPadAxisName, XYPadDirection, XYPadValue } from "./xy-pad-math";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Replaceable text, for example to translate. */
export type XYPadMessages = {
  mixed: string;
  /** Read with the point, from each axis's name and value. */
  value: (x: string, y: string) => string;
};

export const defaultMessages: XYPadMessages = {
  mixed: "Mixed",
  value: (x, y) => `${x}, ${y}`,
};

/** What changed, and whether it came from the pad, the keyboard or a field. */
export type XYPadDetail = { axes: XYPadAxisName[]; source: "pointer" | "keyboard" | "field" };

export type XYPadProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> & {
  /** The committed value. Your app owns it. */
  value: XYPadValue;
  /** Called once per finished drag, key press or field edit, for saving and undo. */
  onValueCommit: (value: XYPadValue, detail: XYPadDetail) => void;
  /** Called with live values, and with the starting value when a drag is cancelled. */
  onValueChange?: (value: XYPadValue, detail: XYPadDetail) => void;
  xAxis: XYPadAxis;
  yAxis: XYPadAxis;
  /** Which way larger Y values run on the surface. */
  yDirection?: XYPadDirection;
  /** Accessible name of the pad, such as "Shadow offset". */
  label: string;
  disabled?: boolean;
  readOnly?: boolean;
  /** The point's press transition. Reduced motion is always honored. */
  motion?: boolean;
  messages?: Partial<XYPadMessages>;
};

export type XYPadContextValue = {
  /** The live value while editing, otherwise the committed value. */
  value: XYPadValue;
  committed: XYPadValue;
  xAxis: XYPadAxis;
  yAxis: XYPadAxis;
  yDirection: XYPadDirection;
  label: string;
  disabled: boolean;
  readOnly: boolean;
  dragging: boolean;
  pointerFocus: boolean;
  motion: boolean;
  messages: XYPadMessages;
  trackRef: { current: HTMLDivElement | null };
  thumbRef: { current: HTMLDivElement | null };
  surfaceHandlers: {
    onPointerDown: (event: PointerEvent<HTMLDivElement>) => void;
    onPointerMove: (event: PointerEvent<HTMLDivElement>) => void;
    onPointerUp: (event: PointerEvent<HTMLDivElement>) => void;
    onPointerCancel: (event: PointerEvent<HTMLDivElement>) => void;
    onLostPointerCapture: (event: PointerEvent<HTMLDivElement>) => void;
  };
  onThumbKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
  onThumbBlur: () => void;
  previewAxis: (axis: XYPadAxisName, value: number) => void;
  commitAxis: (axis: XYPadAxisName, value: number) => void;
};

export const XYPadContext = createContext<XYPadContextValue | null>(null);

/** The value, axes and state of the nearest XYPad, for custom parts. */
export function useXYPad() {
  const context = useContext(XYPadContext);
  if (!context) throw new Error("XY Pad parts must be rendered inside <XYPad>.");
  return context;
}

